DrawFramedTitlebox equ 0x42AC
SetTableBegintoAofHL equ 0x42B1
printNumber equ 0x42C4
todo_SomethingwithDigits equ 0x42C8
printDeciCredit equ 0x4317
CurHomeinFrame equ 0x44A7
printStringFollowingByte equ 0x44E5
printString equ 0x44E9
printStringA equ 0x4523
setColors equ 0x465C
drawFrame equ 0x4753
CommanderStatus equ 0x4954
getRank equ 0x4A66
