; ZX Spectrum: buy_cargo (&E6AE)
; Key 2 (docked only): the buy cargo screen.
BuyGoods:
    ld a,(Missionflag)
    bit 5,a
    jr nz,refuseBacktoInventory
    ld a,(FlightMode)
    and a
    jr z,MarketBuyGoods
    ld a,0x5B
    ld de,0x4B32
    ld hl,0x1401  ; text cursor position for the message
    call drawFlipChart
    ld a,0x32
    ld (circleOffsetXlo),a
    ld a,0x00
    ld (circleOffsetY),a
    ld a,0x0C
    ld (circleOffsetXhi),a
    ld a,0x2D
    ld (drawradius),a
    call DrawCircle
    call WaitForKeypress
    cp 0x4A
    jr nz,refuseBacktoInventory
    ld (largeCargoBay),a
    xor a
    ld (cargoSpaceFree),a
    ld hl,0x39E9
    ld b,0x11
initMissionSupernova:
    ld (hl),a
    inc hl
    djnz initMissionSupernova
    ld hl,0x3A2E
    set 5,(hl)
refuseBacktoInventory:
    ld a,0x0C
    ld (Viewdirection),a
    call longDelay
    jp Inventory
MarketBuyGoods:
    call drawFrame
    call printFollowingTokenWithSpace
    db 0x0C
    ld a,0xFF
    call CallprintString
    ld de,0x4675
    call setColors
    call setPointerstoBeginofInventories
    ld hl,0x3A1B
    ld (0xEFFA),hl
mbloopEntries:
    ld hl,(0xEFF6)
    inc hl
    ld (0xEFF6),hl
    call askBuyGood
    jr c,LAB_ram_08db
    call bufferCharXY
LAB_ram_08c0:
    call printInputQuestionforQuantity
    ld hl,buyQuantityofGood
    call getInputForFunctionHL
    jr nc,LAB_ram_08d5
    cp 0x01
    jr z,LAB_ram_08c0
    cp 0x02
    jr z,LAB_ram_08d8
    jr loc_08E4
LAB_ram_08d5:
    call printWithTokens03n07
LAB_ram_08d8:
    call restoreCharXY
LAB_ram_08db:
    ld hl,0x3F55
    inc (hl)
    ld a,(hl)
    cp 0x11
    jr c,mbloopEntries
loc_08E4:
    jp Inventory
    db "!",0x00,"X",0xCD,0xF0,0x08,0xCD,0xF0,0x08,0x06,0x00,"w#",0x10,0xFC,0xC9
LAB_ram_08f7:
    call ClearCharAtpos
    call restore_trade_state
    jr todoInputNumber1to9
; ZX Spectrum: read_trade_quantity (&E776)
; Reads a one- or two-digit quantity; HL is the row handler (buyQuantityofGood, sellQuantityofGood or the equipment handler), called as each digit is typed.
getInputForFunctionHL:
    ld (storedCallAddress),hl
todoInputNumber1to9:
    xor a
    ld (todo_storestringnumber),a
loopWaitforValidInput:
    call WaitForKeypress
    cp 0x0D
    jr z,doActionforReturn
    cp 0x31
    jr c,loopWaitforValidInput
    cp 0xFE
    jr z,loopWaitforValidInput
    cp 0x3A
    jr nc,LAB_ram_095f
    ld b,a
    sub 0x30
    ld (todo_storestringnumber),a
    ld a,b
    call printString
    ld hl,(storedCallAddress)
    call CallJPHL
    jr c,LAB_ram_095f
todoInputNumber0to9:
    call WaitForKeypress
    cp 0x0D
    ret z
    cp 0x30
    jr c,todoInputNumber0to9
    cp 0xFE
    jr z,LAB_ram_08f7
    cp 0x3A
    jr nc,LAB_ram_095f
    ld d,a
    sub 0x30
    ld b,a
    ld hl,todo_storestringnumber
    ld a,(hl)
    add a,a
    ld c,a
    add a,a
    add a,a
    add a,c
    add a,b
    ld (hl),a
    ld a,d
    call printString
    call restore_trade_state
    ld hl,(storedCallAddress)
    call CallJPHL
    jr c,LAB_ram_095f
    and a
    ret
doActionforReturn:
    ld a,0x02
LAB_ram_095f:
    scf
    ret
; Prints message token 3 (with space) then token 7, then ends via the error beep/delay tail
printWithTokens03n07:
    call printFollowingTokenWithSpace
    db 0x03
    call printStringFollowingByte
    db 0x07
    jp SUB_ram_09c4
; Trampoline: jumps to the address in HL, so `call CallJPHL` acts as an indirect call
CallJPHL:
    jp (hl)
; ZX Spectrum: buy_commodity_row (&E7DB)
buyQuantityofGood:
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    ld b,a
    ld hl,(0xEFFA)
    ld a,(hl)
    sub b
    jr c,errorforWrongQuantity
    ld (hl),a
bgLoopThroughStationInventory:
    ld hl,(0xEFF8)
    ld e,(hl)
    inc hl
    ld d,(hl)
    call tryPayForGood
    jr c,errorforNotEnoughCash
    djnz bgLoopThroughStationInventory
    call todoReturnPressed
    ld a,(todo_storestringnumber)
    ld b,a
    jr nc,LAB_ram_099a
    ld hl,0x39FA
    ld a,(hl)
    sub b
    jr c,errorforNotEnoughCapacity
    ld (hl),a
LAB_ram_099a:
    ld hl,(0xEFF6)
    ld a,(hl)
    add a,b
    jr c,errorforNotEnoughCapacity
    ld (hl),a
    ld a,(storedByteVariable)
    call chkForIllegalGoods
    and a
    ret
errorforWrongQuantity:
    ld a,0xB0
    jr bgprintError
; Trade error: loads message token &C5 and falls into the shared error printer
errorforNotEnoughCash:
    ld a,0xC5
    jr bgprintError
errorforNotEnoughCapacity:
    ld a,0xCE
bgprintError:
    push af
    call printFollowingTokenWithSpace
    db 0x03
    pop af
    call printString
    call printStringFollowingByte
    db "?"
    call restore_trade_state
; Error/finish tail for the trade screen: key sound, long delay, returns A=1 with carry set
SUB_ram_09c4:
    call sfxForKeyInput
    call longDelay
    ld a,0x01
    scf
    ret
; ZX Spectrum: snapshot_trade_state (&E83C)
; Saves the state a trade can change (cash, this row's market stock and held amount, hold space) so restore_trade_state can undo a partial transaction.
snapshot_trade_state:
    ld hl,(creditsHighWord)
    ld (tmpMoney),hl
    ld hl,(creditsLowWord)
    ld (tmpLoMoney),hl
    ld hl,(0xEFFA)
    ld a,(hl)
    ld (BYTE_ram_0a3b),a
    ld hl,(0xEFF6)
    ld a,(hl)
    ld (BYTE_ram_0a3a),a
    ld a,(cargoSpaceFree)
    ld (tmpCargoCapacity),a
    ret
; ZX Spectrum: restore_trade_state (&E85D)
; Writes the snapshot made by snapshot_trade_state back.
restore_trade_state:
    ld hl,(tmpMoney)
    ld (creditsHighWord),hl
    ld hl,(tmpLoMoney)
    ld (creditsLowWord),hl
    ld hl,(0xEFFA)
    ld a,(BYTE_ram_0a3b)
    ld (hl),a
    ld hl,(0xEFF6)
    ld a,(BYTE_ram_0a3a)
    ld (hl),a
    ld a,(tmpCargoCapacity)
    ld (cargoSpaceFree),a
    ret
; Clears the prompt line and prints the quantity question for the chosen good
printInputQuestionforQuantity:
    call clrLine0x15
    ld a,0x01
    ld (todoSomePrintFlag),a
    call printStringFollowingByte
    db 0xCC
    call printStringFollowingByte
    db "("
    ld a,0xD0
    ld b,a
    ld a,(storedByteVariable)
    add a,b
    call printString
    call printStringFollowingByte
    db ")"
    call printStringFollowingByte
    db "/"
    call parseStoredToken
    call printStringFollowingByte
    db " "
    ld a,0x3F
    jp CallprintString
tmpLoMoney:
    db 0x00,0x00
tmpMoney:
    db 0x00,0x00
BYTE_ram_0a3a:
    db 0x00
BYTE_ram_0a3b:
    db 0x00
tmpCargoCapacity:
    db 0x00
todo_storestringnumber:
    db 0x00
storedCallAddress:
    db 0x00,0x00
; ZX Spectrum: sell_cargo (&E8AE)
; Key 3 (docked only): the sell cargo screen.
SellGoods:
    ld a,(FlightMode)
    and a
    jr nz,CanSell
    ld hl,0x3A2E
    ld a,(hl)
    bit 5,a
    jr z,CanSell
    res 5,(hl)
    ld hl,0x39E0
    inc (hl)
    ld a,0x64
    ld (0x39F8),a
    ld a,0x23
    ld (cargoSpaceFree),a
    ld a,0x0F
    ld de,0x4B37
    ld hl,0x0700
    call printMissionText
    jp Inventory
CanSell:
    call DrawFramedTitlebox
    ld de,0x467A
    call setColors
    ld a,0xCD
    call printPlanetname
    call setPointerstoBeginofInventories
csLoopThroughInventory:
    ld hl,(0xEFF8)
    inc hl
    inc hl
    ld (0xEFF8),hl
    call prQuantityofGoodinCargohold
    jr c,csGotoNextGood
    call bufferCharXY
askForQuantityToSell:
    call printInputQuestionforQuantity
    ld hl,sellQuantityofGood
    call getInputForFunctionHL
    jr c,reAskifNotAllSold
    call printWithTokens03n07
LAB_ram_0a9f:
    call restoreCharXY
    call placeCursor
csGotoNextGood:
    ld hl,0x3F55
    inc (hl)
    ld a,(hl)
    cp 0x11
    jp c,csLoopThroughInventory
    call sub_403E
    call sub_403E
    jr csGotoInventoryScreen
reAskifNotAllSold:
    dec a
    jr z,askForQuantityToSell
    dec a
    jr z,LAB_ram_0a9f
csGotoInventoryScreen:
    jp Inventory
; ZX Spectrum: sell_commodity_row (&E935)
sellQuantityofGood:
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    ld b,a
    ld hl,(0xEFF6)
    ld a,(hl)
    sub b
    jp c,errorforWrongQuantity
    ld (hl),a
    push bc
    call todoReturnPressed
    pop bc
    jr nc,LAB_ram_0ade
    ld a,(cargoSpaceFree)
    add a,b
    ld (cargoSpaceFree),a
LAB_ram_0ade:
    push bc
    ld hl,(0xEFF8)
    ld e,(hl)
    inc hl
    ld d,(hl)
    call getMoney
    pop bc
    djnz LAB_ram_0ade
    and a
    ret
; Points the trade pointers at the start of the cargo hold and the station inventory, resets the row
setPointerstoBeginofInventories:
    ld hl,0x39E8
    ld (0xEFF6),hl
    ld hl,0x3F31
    ld (0xEFF8),hl
    xor a
    ld (storedByteVariable),a
    ret
EquipShip:
    call DrawFramedTitlebox
    ld de,0x467F
    call setColors
    call printStringFollowingByte
    db 0x06
    ld a,0xCF
    call printTokenAndToken0x20
    call printStringFollowingByte
    db 0xB9
    call printStringFollowingByte
    db 0x08
    call CurHomeinFrame
    ld hl,0x2F35
    ld (pointerTblEquipmentprices),hl
    ld a,(presentTechLevel)
    add a,0x02
    cp 0x0C
    jr c,LAB_ram_0b2c
    ld a,0x0E
LAB_ram_0b2c:
    ld (varEQMaxTechlevel),a
    xor a
listAvailableEquipmentloop:
    ld (varEquipmentNumber),a
    and a
    jr nz,LAB_ram_0b3c
    ld a,(FlightMode)
    and a
    jr nz,LAB_ram_0b6e
LAB_ram_0b3c:
    ld a,0x03
    ld (numberOfDigits),a
    ld a,(varEquipmentNumber)
    inc a
    call printNumber
    call printFollowingTokenWithSpace
    db 0x04
    ld b,0x69
    ld a,(varEquipmentNumber)
    add a,b
    call printString
    call printFollowingTokenWithSpace
    db 0x16
    ld hl,(pointerTblEquipmentprices)
    ld a,(hl)
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    inc hl
    ld (pointerTblEquipmentprices),hl
    ld h,0x00
    ld l,a
    call printDeciCredit
    call placeCursor
LAB_ram_0b6e:
    ld a,(varEQMaxTechlevel)
    ld b,a
    ld a,(varEquipmentNumber)
    inc a
    cp b
    jr nz,listAvailableEquipmentloop
eqShoppingloop:
    call clrLine0x15
    call printStringFollowingByte
    db 0x7F
    ld a,0x3F
    call printTokenAndToken0x20
    call snapshot_trade_state
    ld hl,AndsAandReturns
    call getInputForFunctionHL
    jr c,LAB_ram_0b9f
    call placeCursor
    ld a,(todo_storestringnumber)
    and a
    jp z,CommanderStatus
    ld b,a
    ld a,(varEQMaxTechlevel)
    cp b
LAB_ram_0b9f:
    jp c,CommanderStatus
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    call getEquipmentPriceEntry
    ld d,0x00
    ld e,(hl)
    push hl
    call SbcDEfromMoney
    pop hl
    jr c,eqFuel
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    call tryPayForGood
eqFuel:
    jp c,eqErrornotEnoughCash
    ld a,(todo_storestringnumber)
    cp 0x01
    jr nz,equipMissiles
    ld a,(FlightMode)
    and a
    jr nz,eqShoppingloop
    xor a
    ld (fuelPriceByte),a
    call printWithTokens03n07
    ld a,0x46
    call setFuel
    jp EquipShip
equipMissiles:
    cp 0x02
    jr nz,tryEquipLargeCargobay
    ld hl,0x3A01
    ld a,(hl)
    cp 0x04
    jp nc,eqErrorAllPresent
    inc a
    ld (hl),a
    jr eqContinueShopping
tryEquipLargeCargobay:
    cp 0x03
    jr nz,tryEquipECMSystem
    ld a,(largeCargoBay)
    and a
    jp nz,eqErrorEquipmentPresent
    ld hl,0x39FA
    ld a,(hl)
    add a,0x0F
    ld (hl),a
    jr equipIt
tryEquipECMSystem:
    cp 0x04
    jr z,chkIfEquipped
    cp 0x07
    jr c,tryEquipLasers
    cp 0x0D
    jr nc,tryEquipLasers
chkIfEquipped:
    call selectEquipmentOfShip
    ld a,(hl)
    and a
    jp nz,eqErrorEquipmentPresent
equipIt:
    call selectEquipmentOfShip
    ld (hl),0xFF
eqContinueShopping:
    call printWithTokens03n07
    jp eqShoppingloop
tryEquipLasers:
    ld b,0x01
    cp 0x05
    jr z,eqBuildLaserEQScreen
    inc b
    cp 0x06
    jr z,eqBuildLaserEQScreen
    inc b
    cp 0x0D
    jr z,eqBuildLaserEQScreen
    inc b
eqBuildLaserEQScreen:
    ld a,b
    ld (eqLasernumber),a
    neg
    push af
    call drawFrame
    pop bc
    ld a,0x0A
    add a,b
    call SUB_ram_3f25
    ld a,0x0E
    call VerticalPlacement
    ld a,(todo_storestringnumber)
    ld b,0x68
    add a,b
    call printString
    ld a,0x10
    call VerticalPlacement
    xor a
eqListEquipmentdirections:
    ld (varEquipmentNumber),a
    call printFollowingTokenWithSpace
    db 0x0A
    ld a,(varEquipmentNumber)
    add a,0x30
    call printTokenAndToken0x20
    ld a,(varEquipmentNumber)
    add a,0x60
    call CallprintString
    ld a,(varEquipmentNumber)
    inc a
    cp 0x04
    jr c,eqListEquipmentdirections
    call clrLine0x15
    call printStringFollowingByte
    db 0xAF
    call printStringFollowingByte
    db "?"
    call WaitForKeypress
    cp 0x30
    jp c,LAB_ram_0cbf
    cp 0x34
    jp nc,LAB_ram_0cbf
    push af
    call CallprintString
    pop af
    sub 0x30
    ld hl,0x39FB
    call SetTableBegintoAofHL
    ld b,(hl)
    ld a,(eqLasernumber)
    ld (hl),a
    ld a,b
    and a
    jr z,eqLeaveNothingtoRefund
    ld hl,0x8F0B
    call SetTableBegintoAofHL
    ld a,(hl)
    call getEquipmentPriceEntry
    ld d,0x00
    ld e,(hl)
    push hl
    call AddDEtoMoney
    pop hl
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    call getMoney
eqLeaveNothingtoRefund:
    call printWithTokens03n07
    jp EquipShip
LAB_ram_0cbf:
    call restore_trade_state
    jr LAB_ram_0cf7
eqErrornotEnoughCash:
    call errorforNotEnoughCash
    jp eqShoppingloop
AndsAandReturns:
    and a
    ret
; Points HL at the 3-byte price entry of the equipment item number in A
getEquipmentPriceEntry:
    dec a
    ld b,a
    add a,a
    add a,b
    ld hl,0x2F35
    jp SetTableBegintoAofHL
; Points HL at the ship's equipment slot for the selected item (table at &38F8)
selectEquipmentOfShip:
    ld hl,0x39FF
    ld a,(todo_storestringnumber)
    jp SetTableBegintoAofHL
eqErrorAllPresent:
    ld a,0x7C
    jr leaveEQScreen
eqErrorEquipmentPresent:
    ld a,0x68
    ld b,a
    ld a,(todo_storestringnumber)
    add a,b
leaveEQScreen:
    call printTokenAndToken0x20
    call printStringFollowingByte
    db 0x1E
    call SUB_ram_09c4
    call restore_trade_state
LAB_ram_0cf7:
    jp CommanderStatus
varEQMaxTechlevel:
    db 0x00
varEquipmentNumber:
    db 0x00
pointerTblEquipmentprices:
    db 0x00,0x00
eqLasernumber:
    db 0x00,":m",0x0D,0x18,0x04,":m",0x0D,"/",0xA7,">",0xFD,0xCA,"#E"
    db ">",0xFE,0xC3,"#E",0x00
    db 0x00
filemenuvar:
    db 0x00
fmTempStack:
    db 0x00,0x00
; Disk file menu: sets up the screen and patches the text routines, then loops on the load/save choices
FileMenu:
    ld a,0x0D
    ld (Viewdirection),a
    call smc_patchFWTextfunctions
    xor a
    ld (filemenuvar),a
    ld (fmTempStack),sp
LAB_ram_0d38:
    call DrawFramedTitlebox
    ld a,0x01
    call printStringA
Filemenuloop:
    ld sp,(fmTempStack)
    ld de,0x46A2
    call setColors
    call WaitForKeypress
    push af
    call clsFMInputLine
    pop af
    sub 0x31
    jr z,loadGame
    dec a
    jp z,saveGame
    dec a
    jp z,listFilecatalog
    dec a
    jr nz,Filemenuloop
    call SUB_ram_09c4
    call clearKeyBuffer
    ld a,(filemenuvar)
    and a
    ret nz
    xor a
    ret
    db "!m",0x0D,"~/w",0xC3,".",0x0D
todo_inputvalue:
    db 0xFF
; Clears the file-menu input line on screen (30 character cells)
clsFMInputLine:
    ld b,0x1E
    ld hl,0xC3C2
LAB_ram_0d7d:
    push bc
    call DrawBytesMask0
    inc hl
    inc hl
    pop bc
    djnz LAB_ram_0d7d
    ret
colorsLoadGameMenu:
    db "VKYTY"
colorsSavegameMenu:
    db "XKGTG"
loadGame:
    ld hl,0x3E3F
    call InputFilename
loc_0D97:
