    call loadFile
    jp nc,0x6439
    ld c,0x18
    inc e
LAB_ram_0db1:
    ld de,colorsSavegameMenu
    call setColors
    halt
    halt
    halt
    halt
    halt
    halt
    ld a,0x02
    call SUB_ram_0faf
    call WaitForKeypress
    call getAdrLengthSaveGameRam
    di
    ei
    jp nc,LAB_ram_0f85
    call encryptSAV
    call getChecksum
    ld hl,0x3A39
    cp (hl)
    jp nz,LAB_ram_0f95
    xor a
    ld (BYTE_ram_0e31),a
    call CryptRun1
    ld hl,0x3A38
    cp (hl)
    jp nz,LAB_ram_0ded
    ld a,0x01
    ld (BYTE_ram_0e31),a
LAB_ram_0ded:
    ld a,0x01
    ld (filemenuvar),a
    call clsFMInputLine
    ld hl,0x0F01
    ld (charXY),hl
